INSERT INTO `config_info` VALUES (1,'my-xhs-redis.yaml','DEFAULT_GROUP','# Redis 连接配置（从生产 Nacos my-xhs 命名空间导出，2026-08-12）\n# 部署后导入 Nacos：命名空间 my-xhs / DEFAULT_GROUP / dataId=my-xhs-redis.yaml\n# 注意：host 需与云主机实际 IP 一致（建议绑定 EIP 后保持 ${HOST_IP} 或改为新 IP）\nspring:\n  data:\n    redis:\n      host: ${HOST_IP}\n      password: Xhs@2026#Redis\n      port: 6379\n      business:\n        port: 6379\n      cache:\n        port: 6379','0c1c7337101ab217c28bab2ba311c29f','2026-07-11 11:16:50','2026-08-12 15:20:31',NULL,'127.0.0.1','','my-xhs',NULL,NULL,NULL,'text',NULL,''),(2,'nacos-lab.yaml','DEFAULT_GROUP','demo.message: c2-watcher-test\ndemo.version: c2-1.0\ndemo.welcome: C2 手写Watcher验证','e65a528a9c59f78011e51379d1b6290c','2026-07-23 14:45:38','2026-07-24 09:30:23',NULL,'${MICROSERVICE_IP}','','sca-lab-dev',NULL,NULL,NULL,'text',NULL,''),(3,'shared-datasource.yaml','DATASOURCE_GROUP','datasource:\n  url: jdbc:mysql://${HOST_IP}:13306/sca_lab\n  username: root\n  maxPoolSize: 10\n  minIdle: 2\n  connectTimeout: 3000','9a866d6402de27b259092ea592f9f60a','2026-07-23 15:26:20','2026-07-23 15:26:20',NULL,'${MICROSERVICE_IP}','','sca-lab-dev',NULL,NULL,NULL,'text',NULL,''),(4,'shared-redis.yaml','REDIS_GROUP','redis:\n  host: ${HOST_IP}\n  port: 16379\n  timeout: 2000\n  maxTotal: 20','ff3fd586afda6d58aea6fbf24a653aeb','2026-07-23 15:26:20','2026-07-23 15:26:20',NULL,'${MICROSERVICE_IP}','','sca-lab-dev',NULL,NULL,NULL,'text',NULL,''),(6,'my-xhs-common.yaml','DEFAULT_GROUP','# my-xhs 公共配置（从生产 Nacos my-xhs 命名空间导出，2026-08-12）\n# 部署后导入 Nacos：命名空间 my-xhs / DEFAULT_GROUP / dataId=my-xhs-common.yaml\n# 注意：仅覆盖 datasource 密码与 redis 连接；IP 与业务配置见 my-xhs-redis.yaml / 各服务本地 yml\nspring:\n  datasource:\n    password: Xhs@2026#MySQL\n  data:\n    redis:\n      password: Xhs@2026#Redis\n      port: 6379','4ccb87cec267e1fa9c7d94c826cfb7c6','2026-08-03 19:28:30','2026-08-12 15:20:31',NULL,'127.0.0.1','','my-xhs',NULL,NULL,NULL,'text',NULL,''),(7,'my-xhs-gateway.yaml','DEFAULT_GROUP','# 网关密钥配置（从生产 Naco